(7484432, 1191008, 100831, '<td valign="top">Fabulous. This could be an Arbus. Really well caught emotions and the processing is perfect IMO.  Treasure this.</td>', 'Fabulous. This could be an Arbus. Really well caught emotions and the processing is perfect IMO.  Treasure this.', '2016-11-27 16:34:52.000000', NULL, 1),
