(7484435, 1190408, 98565, '<td valign="top">My personal choice for the blue!<br/>What a wonderful moment - still children after all - technically perfect too<br/>Voted earlier</td>', 'My personal choice for the blue!What a wonderful moment - still children after all - technically perfect tooVoted earlier', '2016-11-27 16:36:35.000000', NULL, 1),
(7484436, 1190775, 115814, '<td valign="top">Love how the subject is framed in a graceful arc to isolate it from the clouds. Well done!</td>', 'Love how the subject is framed in a graceful arc to isolate it from the clouds. Well done!', '2016-11-27 16:38:15.000000', NULL, 1),
(7484437, 1190889, 100831, '<td valign="top">So tall, not what I would have expected but spot on nevertheless. I love the clouds at the top. Also, an excellent street shot.</td>', 'So tall, not what I would have expected but spot on nevertheless. I love the clouds at the top. Also, an excellent street shot.', '2016-11-27 16:38:47.000000', NULL, 1),
(7484438, 1190958, 115814, '<td valign="top">Peaceful.</td>', 'Peaceful.', '2016-11-27 16:39:25.000000', NULL, 1),
