(7484441, 1191008, 100393, '<td valign="top">Sensational - I''m glad Im coming back for a commenting pass. I under-rated this previously.<br/> <br/>Such softness and sensitivity; great light, perfectly matched DOF.<br/> <br/>Intimate and engaging. Bumping to a 10.</td>', 'Sensational - I''m glad Im coming back for a commenting pass. I under-rated this previously. Such softness and sensitivity; great light, perfectly matched DOF. Intimate and engaging. Bumping to a 10.', '2016-11-27 16:41:55.000000', NULL, 1),
(7484442, 1190282, 115814, '<td valign="top">Echoed teeth make me smile. I think it might be improved by a vertical orientation and less water, making the subject more prominent in the frame.</td>', 'Echoed teeth make me smile. I think it might be improved by a vertical orientation and less water, making the subject more prominent in the frame.', '2016-11-27 16:42:48.000000', NULL, 1),
(7484444, 1190702, 115814, '<td valign="top">Normally, I''d find the aisle being so centered a distraction, but here it''s effective creating a division between the competing linear motion of the left and right sides of the image. Fascinating and well-conceived compostion.</td>', 'Normally, I''d find the aisle being so centered a distraction, but here it''s effective creating a division between the competing linear motion of the left and right sides of the image. Fascinating and well-conceived compostion.', '2016-11-27 16:46:26.000000', NULL, 1),
(7484445, 1191005, 115814, '<td valign="top">A compelling expression, subject placement, and B/W conversion marred by soft focus of the eyes.</td>', 'A compelling expression, subject placement, and B/W conversion marred by soft focus of the eyes.', '2016-11-27 16:48:17.000000', NULL, 1),
(7484447, 1190921, 115814, '<td valign="top">I''m pretty sure I was that happy once. Nicely done!</td>', 'I''m pretty sure I was that happy once. Nicely done!', '2016-11-27 16:51:36.000000', NULL, 1),
(7484448, 1190744, 115814, '<td valign="top">Lots of character coming through!</td>', 'Lots of character coming through!', '2016-11-27 16:52:14.000000', NULL, 1),
(7484449, 1190897, 115814, '<td valign="top">What a lovely color palette. The blues/aquas/turquoise tones are perfect.</td>', 'What a lovely color palette. The blues/aquas/turquoise tones are perfect.', '2016-11-27 16:53:08.000000', NULL, 1),
(7484450, 1190910, 115814, '<td valign="top">I''m not usually a fan of this long exposure waterfall technique because it''s so often used in isolation of any interesting subject or composition. This is an exception for me. Lovely.</td>', 'I''m not usually a fan of this long exposure waterfall technique because it''s so often used in isolation of any interesting subject or composition. This is an exception for me. Lovely.', '2016-11-27 16:54:50.000000', NULL, 1),
(7484451, 1190907, 115814, '<td valign="top">Nice processing choice on this. The faded colors do justice here beyond creating an excuse for a nostalgic look. In this case it complements the colors of the flower petals, the dress, skin tone and eyes.</td>', 'Nice processing choice on this. The faded colors do justice here beyond creating an excuse for a nostalgic look. In this case it complements the colors of the flower petals, the dress, skin tone and eyes.', '2016-11-27 16:57:13.000000', NULL, 1),
(7484452, 1190955, 115814, '<td valign="top">memories with mixed emotion perhaps? Thought provoking and intense.</td>', 'memories with mixed emotion perhaps? Thought provoking and intense.', '2016-11-27 16:59:01.000000', NULL, 1),
(7484454, 1190874, 115814, '<td valign="top">Got to wonder what that smudge is repairing. Love the graceful arcs and lines.</td>', 'Got to wonder what that smudge is repairing. Love the graceful arcs and lines.', '2016-11-27 17:00:45.000000', NULL, 1),
(7484455, 1190947, 115814, '<td valign="top">Good detail and subject isolation.</td>', 'Good detail and subject isolation.', '2016-11-27 17:01:44.000000', NULL, 1),
(7484457, 1190984, 115814, '<td valign="top">Terrific blues and gold tones.</td>', 'Terrific blues and gold tones.', '2016-11-27 17:02:35.000000', NULL, 1),
(7484458, 1190928, 115814, '<td valign="top">Layers at all the right places. Nice</td>', 'Layers at all the right places. Nice', '2016-11-27 17:03:20.000000', NULL, 1),
